sysauto_script.script:
var caseGr = new GlideRecord('x_snc_flowops_guest_case');

var threeMinutesAgo = new GlideDateTime(gs.minutesAgoStart(3));

caseGr.addQuery('status', 'open');
caseGr.addQuery('sys_created_on', '<=', threeMinutesAgo);

caseGr.query();

gs.info('[FlowOps Recovery] Rows Found = ' + caseGr.getRowCount());

while (caseGr.next()) {

    try {

        var guestCaseId = caseGr.getUniqueValue();
        var deptName = caseGr.getDisplayValue('department');

        if (
            (deptName == 'Housekeeping' || deptName == 'Engineering') &&
            !gs.nil(caseGr.getValue('assigned_to'))
        ) {
            continue;
        }

        if (
            deptName == 'Vendor' &&
            !gs.nil(caseGr.getValue('assigned_vendor'))
        ) {
            continue;
        }

        gs.info('[FlowOps Recovery] Processing Case: ' +
            caseGr.getDisplayValue());

        var orch = new FO_AIOrchestrator();

        if (deptName == 'Housekeeping') {

            orch.assignHousekeeping(guestCaseId);

        } else if (deptName == 'Engineering') {

            orch.triageEngineering(guestCaseId);

        } else if (deptName == 'Vendor') {

            orch.assignVendor(
                guestCaseId,
                caseGr.getValue('service_subtype'),
                caseGr.getValue('priority'),
                caseGr.getValue('case_detail')
            );
        }

        gs.info('[FlowOps Recovery] Completed Case: ' +
            caseGr.getDisplayValue());

    } catch (ex) {

        gs.error('[FlowOps Recovery] Error for Case ' +
            caseGr.getDisplayValue() +
            ' : ' + ex);
    }
}
